import json
from pathlib import Path

D = Path(__file__).resolve().parent


def wb(k):
    d = json.loads((D / "data" / "wb" / f"{k}.json").read_text())
    return {int(r["date"]): r["value"] for r in (d[1] or []) if r["value"] is not None}


